"use client";

import Link from "next/link";
import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

type MenuItem = {
  label: string;
  href: string;
};

type MobileMenuProps = {
  items: readonly MenuItem[];
};

const FOCUSABLE_ELEMENTS = [
  "a[href]",
  "button:not([disabled])",
  "[tabindex]:not([tabindex='-1'])",
].join(",");

export function MobileMenu({ items }: MobileMenuProps) {
  const [isOpen, setIsOpen] = useState(false);
  const menuId = useId();
  const menuRef = useRef<HTMLDivElement>(null);
  const closeButtonRef = useRef<HTMLButtonElement>(null);

  const closeMenu = useCallback(() => setIsOpen(false), []);

  // Bloqueo de scroll, incluida la posición en iOS.
  useEffect(() => {
    if (!isOpen) return;

    const html = document.documentElement;
    const body = document.body;
    const scrollY = window.scrollY;
    const scrollbarGap = window.innerWidth - html.clientWidth;

    const previous = {
      htmlOverflow: html.style.overflow,
      bodyOverflow: body.style.overflow,
      bodyPosition: body.style.position,
      bodyTop: body.style.top,
      bodyWidth: body.style.width,
      bodyPaddingRight: body.style.paddingRight,
    };

    html.style.overflow = "hidden";
    body.style.overflow = "hidden";
    body.style.position = "fixed";
    body.style.top = `-${scrollY}px`;
    body.style.width = "100%";

    if (scrollbarGap > 0) {
      body.style.paddingRight = `${scrollbarGap}px`;
    }

    return () => {
      html.style.overflow = previous.htmlOverflow;
      body.style.overflow = previous.bodyOverflow;
      body.style.position = previous.bodyPosition;
      body.style.top = previous.bodyTop;
      body.style.width = previous.bodyWidth;
      body.style.paddingRight = previous.bodyPaddingRight;

      window.scrollTo({
        top: scrollY,
        left: 0,
        behavior: "instant" as ScrollBehavior,
      });
    };
  }, [isOpen]);

  // Escape, focus inicial, focus trap y restauración del focus.
  useEffect(() => {
    if (!isOpen) return;

    const previouslyFocused = document.activeElement as HTMLElement | null;
    const focusFrame = requestAnimationFrame(() => {
      closeButtonRef.current?.focus();
    });

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        closeMenu();
        return;
      }

      if (event.key !== "Tab" || !menuRef.current) return;

      const focusable = Array.from(
        menuRef.current.querySelectorAll<HTMLElement>(FOCUSABLE_ELEMENTS),
      );

      if (focusable.length === 0) return;

      const first = focusable[0];
      const last = focusable[focusable.length - 1];

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener("keydown", handleKeyDown);

    return () => {
      cancelAnimationFrame(focusFrame);
      document.removeEventListener("keydown", handleKeyDown);
      previouslyFocused?.focus();
    };
  }, [closeMenu, isOpen]);

  return (
    <>
      <button
        ref={closeButtonRef}
        type="button"
        aria-expanded={isOpen}
        aria-controls={menuId}
        className="relative z-[60] min-h-11 min-w-11 px-4 text-sm font-medium tracking-wide text-current focus-visible:outline-2 focus-visible:outline-offset-4 md:hidden"
        onClick={() => setIsOpen((current) => !current)}
      >
        {isOpen ? "Cerrar" : "Menú"}
      </button>

      <div
        ref={menuRef}
        id={menuId}
        role="dialog"
        aria-modal="true"
        aria-label="Navegación principal"
        aria-hidden={!isOpen}
        data-open={isOpen}
        className={[
          "fixed inset-0 z-50 h-[100svh] overflow-y-auto overscroll-contain",
          "bg-neutral-950 text-stone-50",
          "transition-[transform,visibility] duration-200 ease-in",
          "data-[open=false]:invisible data-[open=false]:translate-y-full",
          "data-[open=true]:visible data-[open=true]:translate-y-0",
          "data-[open=true]:duration-300 data-[open=true]:ease-out",
          "motion-reduce:transition-none",
        ].join(" ")}
      >
        <nav
          aria-label="Menú móvil"
          className="flex min-h-[100svh] items-end px-6 pb-10 pt-24 sm:px-10 sm:pb-14"
        >
          <ul className="w-full border-t border-white/20">
            {items.map((item, index) => (
              <li
                key={item.href}
                className={[
                  "border-b border-white/20 transition-[opacity,transform]",
                  "duration-200 ease-out motion-reduce:transition-none",
                  isOpen
                    ? "translate-y-0 opacity-100"
                    : "translate-y-4 opacity-0",
                ].join(" ")}
                style={{
                  transitionDelay: isOpen ? `${index * 40 + 80}ms` : "0ms",
                }}
              >
                <Link
                  href={item.href}
                  onClick={closeMenu}
                  className={[
                    "flex min-h-20 items-center py-4",
                    "text-[clamp(2rem,10vw,4.5rem)] font-medium leading-none",
                    "transition-opacity hover:opacity-60",
                    "focus-visible:outline-2 focus-visible:outline-offset-[-2px]",
                  ].join(" ")}
                >
                  {item.label}
                </Link>
              </li>
            ))}
          </ul>
        </nav>
      </div>
    </>
  );
}
```

Uso:

```tsx
<MobileMenu
  items={[
    { label: "Inicio", href: "/" },
    { label: "Proyectos", href: "/#proyectos" },
    { label: "Contacto", href: "/contacto" },
  ]}
/>
```

Mantiene la posición exacta de scroll, evita el salto causado por la desaparición de la scrollbar, usa `100svh` para Safari móvil y restaura el foco al cerrar.
